import {CenterBaseline} from '@react-spectrum/s2/CenterBaseline';
import {getIcon} from './promptfield';
import {
  Chat,
  ExecutionTrace,
  ExecutionTraceItem,
  MessageFeedback,
  MessageSuggestion,
  MessageSuggestionList,
  ResponseStatus,
  ResponseStatusPanel,
  ResponseStatusTitle,
  Thread,
  ThreadItem,
  TokenFieldValue,
  UserMessage
} from '@react-spectrum/ai';
import * as loaders from '@react-spectrum/ai/loader';
import {prose} from '@react-spectrum/ai/style' with {type: 'macro'};
import {ReactNode, useEffect, useMemo, useRef, useState} from 'react';
import {style} from '@react-spectrum/s2/style' with {type: 'macro'};

let initialResponses = [
  {
    id: 0,
    type: 'user',
    content: 'Can you help me plan a short trip to the mountains this weekend?'
  },
  {
    id: 1,
    type: 'system',
    content: 'Sure! How many days do you have, and do you prefer hiking, skiing, or just relaxing?'
  },
  {
    id: 2,
    type: 'user',
    content: 'Two days, and I want a mix of hiking and relaxing.'
  },
  {
    id: 3,
    type: 'system',
    content:
      'Day one: a moderate morning hike with a scenic overlook, then lunch in town. Day two: a slow start, a short walk, and time to unwind before heading back.'
  }
];

interface ExecutionStep {
  id: number;
  label: string;
  status: 'pending' | 'success';
  detail?: string;
}

type StreamingMessage =
  | {id: number | string; type: 'user'; content: string}
  | {id: number | string; type: 'system'; content: string; isStreaming?: boolean}
  | {
      id: number | string;
      type: 'status';
      status: 'pending' | 'success';
      steps: ExecutionStep[];
    }
  | {id: number | string; type: 'suggestions'; suggestions: TokenFieldValue[]};

export interface VirtualizedStreamingChatProps {
  children: (onSend: (prompt: TokenFieldValue) => void, isGenerating: boolean) => ReactNode;
  /** Suggestions shown at the end of the thread. Hidden while a response is streaming in. */
  suggestions?: TokenFieldValue[];
  onSelectSuggestion?: (suggestion: TokenFieldValue) => void;
}

export function VirtualizedStreamingChat(props: VirtualizedStreamingChatProps) {
  let {children, suggestions, onSelectSuggestion} = props;
  let [messages, setMessages] = useState<StreamingMessage[]>(
    initialResponses as StreamingMessage[]
  );
  let nextId = useRef(initialResponses.length);
  let [isGenerating, setGenerating] = useState(false);
  let timeouts = useRef<NodeJS.Timeout[]>([]);

  function handleSend(prompt: TokenFieldValue) {
    setGenerating(true);
    // user message added first so its announcement plays before the status updates
    setMessages(prev => [
      ...prev,
      {id: nextId.current++, type: 'user', content: prompt.toString()}
    ]);

    // Starts a new grouped status message containing a single pending execution trace step.
    function startToolGroup(label: string) {
      setMessages(prev => [
        ...prev,
        {
          id: nextId.current++,
          type: 'status',
          status: 'pending',
          steps: [{id: nextId.current++, label, status: 'pending'}]
        }
      ]);
    }

    // Adds a new step to the trailing status group if one is still open, otherwise starts a new group.
    function addStep(label: string) {
      setMessages(prev => {
        let last = prev[prev.length - 1];
        let newStep: ExecutionStep = {id: nextId.current++, label, status: 'pending'};
        if (last?.type === 'status' && last.status === 'pending') {
          return [
            ...prev.slice(0, -1),
            {
              ...last,
              steps: [
                ...last.steps.slice(0, -1),
                {...last.steps[last.steps.length - 1], status: 'success'},
                newStep
              ]
            }
          ];
        }
        return [
          ...prev,
          {id: nextId.current++, type: 'status', status: 'pending', steps: [newStep]}
        ];
      });
    }

    // Completes the last step of the trailing status group.
    function completeStep(detail: string) {
      setMessages(prev => {
        let last = prev[prev.length - 1];
        if (last?.type !== 'status') {
          return prev;
        }
        let steps = last.steps.slice();
        let step = steps[steps.length - 1];
        steps[steps.length - 1] = {...step, status: 'success', detail};
        return [...prev.slice(0, -1), {...last, steps}];
      });
    }

    // Marks the trailing status group as complete once all of its steps have finished.
    function completeGroup() {
      setMessages(prev => {
        let last = prev[prev.length - 1];
        if (last?.type !== 'status') {
          return prev;
        }
        return [...prev.slice(0, -1), {...last, status: 'success'}];
      });
    }

    function streamText(content: string) {
      setMessages(prev => [
        ...prev,
        {id: nextId.current++, type: 'system', content: '', isStreaming: true}
      ]);
      let tokens = content.split(' ');
      let accumulated = '';
      tokens.forEach((token, i) => {
        setTimeout(() => {
          accumulated += (i === 0 ? '' : ' ') + token;
          let isLastToken = i === tokens.length - 1;
          setMessages(prev =>
            prev.map(m =>
              m.type === 'system' && m.isStreaming
                ? {...m, content: accumulated, isStreaming: !isLastToken}
                : m
            )
          );
        }, i * 80);
      });
    }

    let addTimeout = (callback: () => void, delay: number) => {
      let timeout = setTimeout(callback, delay);
      timeouts.current.push(timeout);
      return timeout;
    };

    let timestamp = 0;
    let toolCallDuration = 1000;
    // Status added after a short delay so the user message announcement plays first.
    addTimeout(() => startToolGroup('Searching Yelp'), (timestamp += 500));
    addTimeout(
      () => completeStep('Found 12 restaurants near the trailhead.'),
      (timestamp += toolCallDuration)
    );
    addTimeout(() => addStep('Searching Google Maps'), (timestamp += 500));
    addTimeout(
      () => completeStep('Compared ratings and walking distances.'),
      (timestamp += toolCallDuration)
    );
    addTimeout(() => addStep('Searching TripAdvisor'), (timestamp += 500));
    addTimeout(
      () => completeStep('Checked recent reviews for the top matches.'),
      (timestamp += toolCallDuration)
    );
    addTimeout(() => addStep('Filtering by distance'), (timestamp += 500));
    addTimeout(
      () => completeStep('Narrowed the list down to places within range.'),
      (timestamp += toolCallDuration)
    );
    addTimeout(() => completeGroup(), (timestamp += 200));

    let replyContent =
      'A few good options within range: Trailhead Café for a quick bite, Base Camp Diner for ' +
      'something heartier, and Riverside Grill if you want a sit-down meal.';
    addTimeout(() => streamText(replyContent), (timestamp += 500));

    let streamEndTimestamp = timestamp + (replyContent.split(' ').length - 1) * 80 + 500;
    addTimeout(() => setGenerating(false), streamEndTimestamp);
  }

  useEffect(
    () => () => {
      timeouts.current.forEach(clearTimeout);
    },
    []
  );

  let items = useMemo<StreamingMessage[]>(() => {
    if (isGenerating || !suggestions) {
      return messages;
    }
    return [...messages, {id: 'suggestions', type: 'suggestions', suggestions}];
  }, [messages, isGenerating, suggestions]);

  return (
    <Chat>
      <Thread items={items} aria-label="Chat thread">
        {(msg: StreamingMessage) => {
          if (msg.type === 'user') {
            return (
              <ThreadItem
                textValue={msg.content}
                styles={style({display: 'flex', justifyContent: 'end'})}>
                <UserMessage>{msg.content}</UserMessage>
              </ThreadItem>
            );
          }
          if (msg.type === 'status') {
            return <StatusThreadItem msg={msg} />;
          }
          if (msg.type === 'suggestions') {
            return (
              <ThreadItem textValue="Suggestions">
                <MessageSuggestionList title="Suggestions" styles={style({marginTop: 40})}>
                  {msg.suggestions.map((s, i) => (
                    <MessageSuggestion key={i} onPress={() => onSelectSuggestion?.(s)}>
                      <SuggestionLabel value={s} />
                    </MessageSuggestion>
                  ))}
                </MessageSuggestionList>
              </ThreadItem>
            );
          }
          return (
            <ThreadItem textValue={msg.content} isStreaming={msg.isStreaming}>
              <div role="document">
                <p className={prose()}>{msg.content || ''}</p>
              </div>
              {!msg.isStreaming && <MessageFeedback />}
            </ThreadItem>
          );
        }}
      </Thread>
      {children(handleSend, isGenerating)}
    </Chat>
  );
}

function StatusThreadItem({msg}: {msg: Extract<StreamingMessage, {type: 'status'}>}) {
  let isStreaming = msg.status === 'pending';
  let lastStep = msg.steps[msg.steps.length - 1];
  let title = isStreaming
    ? `${lastStep.label}…`
    : msg.steps.length > 1
      ? `Completed ${msg.steps.length} steps`
      : lastStep.label;
  let announcement = isStreaming ? `${lastStep.label}…` : `${title} complete`;
  return (
    <ThreadItem textValue={announcement} isStreaming={isStreaming} shouldAnnounceOnMount>
      <ResponseStatus status={isStreaming ? 'pending' : 'success'}>
        <ResponseStatusTitle pixelLoader={loaders.mega}>{title}</ResponseStatusTitle>
        <ResponseStatusPanel>
          <ExecutionTrace>
            {msg.steps.map(step => (
              <ExecutionTraceItem
                key={step.id}
                status={step.status}
                detail={
                  step.detail && (
                    <p className={style({font: 'body-sm', margin: 0})}>{step.detail}</p>
                  )
                }>
                {step.label}
              </ExecutionTraceItem>
            ))}
          </ExecutionTrace>
        </ResponseStatusPanel>
      </ResponseStatus>
    </ThreadItem>
  );
}

let suggestionToken = style({
  outlineStyle: {
    default: 'solid',
    isPlaceholder: 'dashed'
  },
  outlineWidth: 1,
  outlineColor: {
    default: 'transparent-overlay-1000/20',
    isPlaceholder: 'transparent-overlay-1000/40'
  },
  outlineOffset: -1,
  borderRadius: 'pill',
  paddingX: 8,
  paddingY: 0,
  fontSize: 'ui',
  display: 'inline-flex',
  alignItems: 'baseline',
  gap: 4,
  verticalAlign: 'baseline'
});

function SuggestionLabel({value}: {value: TokenFieldValue}) {
  return (
    <>
      {value.segments.map((seg, i) =>
        seg.type === 'token' ? (
          <span
            key={i}
            className={suggestionToken({isPlaceholder: seg.value?.type === 'placeholder'})}>
            {getIcon(seg) && <CenterBaseline>{getIcon(seg)}</CenterBaseline>}
            {seg.text}
          </span>
        ) : (
          seg.text
        )
      )}
    </>
  );
}

// @vitest-environment jsdom

import { act, startTransition } from "react";
import { afterAll, afterEach, expect, it, vi } from "vitest";
import { useReplayRenderWait } from "./replayBoundaryStream";
import { useRunManager } from "./runManager";

type Family = { current: unknown };
type RendererInternals = {
  setRefreshHandler: (resolve: (type: unknown) => Family | undefined) => void;
  scheduleRefresh: (
    root: unknown,
    update: { staleFamilies: Set<Family>; updatedFamilies: Set<Family> },
  ) => void;
};

let renderer: RendererInternals | undefined;
const fiberRoots = new Set<unknown>();
vi.stubGlobal("IS_REACT_ACT_ENVIRONMENT", true);
vi.stubGlobal("__REACT_DEVTOOLS_GLOBAL_HOOK__", {
  supportsFiber: true,
  inject: (internals: RendererInternals) => {
    renderer = internals;
    return 1;
  },
  onScheduleFiberRoot: () => {},
  onCommitFiberRoot: (_id: number, root: unknown) => fiberRoots.add(root),
  onCommitFiberUnmount: () => {},
});
const { flushSync } = await import("react-dom");
const { cleanup, render } = await import("@testing-library/react");

afterEach(() => {
  cleanup();
  vi.useRealTimers();
});
afterAll(() => vi.unstubAllGlobals());

let rendered = "";

const refresh = (before: unknown, after: unknown) => {
  const family: Family = { current: after };
  renderer!.setRefreshHandler((type) =>
    type === before || type === after ? family : undefined,
  );
  for (const fiberRoot of fiberRoots) {
    renderer!.scheduleRefresh(fiberRoot, {
      staleFamilies: new Set(),
      updatedFamilies: new Set([family]),
    });
  }
};

const deferred = () => {
  let resolve!: () => void;
  const promise = new Promise<void>((done) => {
    resolve = done;
  });
  return { promise, resolve };
};

it("keeps an in-flight run and coalesced follow-up through Fast Refresh, then aborts on unmount", async () => {
  const first = deferred();
  const second = deferred();
  const onRun = vi
    .fn()
    .mockImplementationOnce(async () => first.promise)
    .mockImplementationOnce(async () => second.promise);
  const onFinish = vi.fn();
  const onCancel = vi.fn();
  let manager!: ReturnType<typeof useRunManager>;
  const useManager = () => {
    manager = useRunManager({ onRun, onFinish, onCancel });
  };
  const Before = () => {
    rendered = "before";
    useManager();
    return null;
  };
  const After = () => {
    rendered = "after";
    useManager();
    return null;
  };
  const view = render(<Before />);

  act(() => manager.schedule());
  await act(async () => {});
  expect(onRun).toHaveBeenCalledOnce();
  const signal = onRun.mock.calls[0]![0] as AbortSignal;
  act(() => manager.schedule());

  await act(async () => refresh(Before, After));
  expect(rendered).toBe("after");
  expect(signal.aborted).toBe(false);
  expect(onCancel).not.toHaveBeenCalled();

  await act(async () => first.resolve());
  expect(onFinish).toHaveBeenCalledOnce();
  expect(onRun).toHaveBeenCalledTimes(2);
  const followUpSignal = onRun.mock.calls[1]![0] as AbortSignal;
  expect(followUpSignal.aborted).toBe(false);

  view.unmount();
  await act(async () => {});
  expect(followUpSignal.aborted).toBe(true);
  await act(async () => second.resolve());
});

it("keeps a render waiter pending through Fast Refresh until its ticket commits, then releases it on unmount", async () => {
  vi.useFakeTimers();
  let waitForRender!: ReturnType<typeof useReplayRenderWait>;
  const useWaiter = () => {
    waitForRender = useReplayRenderWait();
  };
  const Before = () => {
    rendered = "before";
    useWaiter();
    return null;
  };
  const After = () => {
    rendered = "after";
    useWaiter();
    return null;
  };
  const view = render(<Before />);
  let resolved = false;
  const wait = waitForRender().then(() => {
    resolved = true;
  });

  startTransition(() => {
    vi.runOnlyPendingTimers();
  });
  flushSync(() => refresh(Before, After));
  expect(rendered).toBe("after");
  await Promise.resolve();
  expect(resolved).toBe(false);

  await act(async () => {});
  await wait;
  expect(resolved).toBe(true);

  let releasedOnUnmount = false;
  const unmountWait = waitForRender().then(() => {
    releasedOnUnmount = true;
  });
  vi.runOnlyPendingTimers();
  view.unmount();
  await act(async () => {});
  await unmountWait;
  expect(releasedOnUnmount).toBe(true);
});

// @vitest-environment jsdom

import {
  act,
  render,
  waitFor as waitForAssertion,
} from "@testing-library/react";
import { Suspense, useState, type FC } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { useAui } from "@assistant-ui/store";
import { ToolResponse } from "assistant-stream";
import { AssistantRuntimeProvider } from "../../AssistantRuntimeProvider";
import {
  useAssistantTransportRuntime,
  useAssistantTransportSendCommand,
} from "./useAssistantTransportRuntime";
import { REPLAY_CONTENT_LENGTH_HEADER } from "./replayBoundaryStream";
import type {
  AssistantTransportCommand,
  AssistantTransportOptions,
  AssistantTransportStateConverter,
} from "./types";

const nextTask = () => new Promise((resolve) => setTimeout(resolve, 0));

const waitFor = (assertion: () => void) =>
  waitForAssertion(assertion, { interval: 10 });

const converter: AssistantTransportStateConverter<unknown> = (
  _state,
  meta,
) => ({
  messages: [],
  isRunning: meta.isSending,
});

const createMessageCommand = (
  text: string,
  id?: string,
): AssistantTransportCommand => ({
  type: "add-message",
  message: {
    role: "user",
    ...(id !== undefined && { id }),
    parts: [{ type: "text", text }],
  },
  parentId: null,
  sourceId: null,
});

const createStreamResponse = () => {
  let controller!: ReadableStreamDefaultController<Uint8Array>;
  const stream = new ReadableStream<Uint8Array>({
    start(c) {
      controller = c;
    },
  });
  return {
    response: new Response(stream, { status: 200 }),
    push: (text: string) => controller.enqueue(new TextEncoder().encode(text)),
    close: () => controller.close(),
  };
};

type StreamResponse = ReturnType<typeof createStreamResponse>;

type RecordedRequest = {
  url: string;
  init: RequestInit;
  body: Record<string, any>;
};

const installFetch = () => {
  const requests: RecordedRequest[] = [];
  const servers: StreamResponse[] = [];

  vi.stubGlobal(
    "fetch",
    async (url: RequestInfo | URL, init: RequestInit = {}) => {
      requests.push({
        url: String(url),
        init,
        body: JSON.parse(init.body as string),
      });
      const server = createStreamResponse();
      servers.push(server);
      return server.response;
    },
  );

  return { requests, servers };
};

const installPendingFetch = () => {
  const requests: RecordedRequest[] = [];
  const pending: {
    resolve: (response: Response) => void;
    reject: (reason: unknown) => void;
  }[] = [];

  vi.stubGlobal("fetch", (url: RequestInfo | URL, init: RequestInit = {}) => {
    requests.push({
      url: String(url),
      init,
      body: JSON.parse(init.body as string),
    });

    return new Promise<Response>((resolve, reject) => {
      pending.push({ resolve, reject });
      init.signal?.addEventListener(
        "abort",
        () => reject(init.signal?.reason),
        {
          once: true,
        },
      );
    });
  });

  return { requests, pending };
};

const mountRuntime = (
  options?: Partial<AssistantTransportOptions<unknown>>,
) => {
  const captured: {
    aui?: ReturnType<typeof useAui>;
    sendCommand?: (command: AssistantTransportCommand) => void;
  } = {};
  const Capture: FC = () => {
    captured.aui = useAui();
    captured.sendCommand = useAssistantTransportSendCommand();
    return null;
  };
  const App: FC = () => {
    const runtime = useAssistantTransportRuntime({
      initialState: {},
      api: "https://example.com/api",
      headers: {},
      converter,
      ...options,
    });
    return (
      <AssistantRuntimeProvider runtime={runtime}>
        <Capture />
      </AssistantRuntimeProvider>
    );
  };
  const utils = render(<App />);
  return {
    aui: () => captured.aui!,
    sendCommand: (command: AssistantTransportCommand) =>
      captured.sendCommand!(command),
    ...utils,
  };
};

afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

describe("useAssistantTransportRuntime", () => {
  it.each([
    {
      name: "line",
      protocol: "assistant-transport" as const,
      response: "data: [DONE]\n\n",
      limits: { maxStreamLineLength: 5 },
      expectedError: "maxLineLength",
    },
    {
      name: "event",
      protocol: "assistant-transport" as const,
      response: "data: a\ndata: b\n\n",
      limits: { maxStreamLineLength: 7, maxStreamEventLength: 2 },
      expectedError: "maxEventLength",
    },
    {
      name: "data-stream line",
      protocol: "data-stream" as const,
      response: '0:"hello"\n',
      limits: { maxStreamLineLength: 4 },
      expectedError: "maxLineLength",
    },
  ])("forwards the configured $name limit", async (testCase) => {
    const onError = vi.fn();
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue(new Response(testCase.response)),
    );

    const { aui, sendCommand } = mountRuntime({
      protocol: testCase.protocol,
      ...testCase.limits,
      onError,
    });
    await waitFor(() =>
      expect(
        (aui().thread.getState().extras as { sendCommand?: unknown })
          ?.sendCommand,
      ).toBeTypeOf("function"),
    );

    act(() => sendCommand(createMessageCommand("hello")));

    await waitFor(() =>
      expect(onError).toHaveBeenCalledWith(
        expect.objectContaining({
          message: expect.stringContaining(testCase.expectedError),
        }),
        expect.anything(),
      ),
    );
  });

  it.each([false, 0, "", null])(
    "preserves the falsy tool artifact %j",
    async (artifact) => {
      const fetchMock = installFetch();
      const { aui } = mountRuntime({
        converter: (_state, meta) => ({
          messages: [
            {
              id: "a1",
              role: "assistant",
              content: [
                {
                  type: "tool-call",
                  toolCallId: "tc1",
                  toolName: "probe",
                  args: {},
                  argsText: "{}",
                },
              ],
              createdAt: new Date(0),
              status: { type: "requires-action", reason: "tool-calls" },
              metadata: {
                unstable_state: {},
                unstable_annotations: [],
                unstable_data: [],
                steps: [],
                custom: {},
              },
            },
          ],
          isRunning: meta.isSending,
        }),
      });

      await waitFor(() =>
        expect(
          aui()
            .thread.message({ id: "a1" })
            .part({ toolCallId: "tc1" })
            .getState().type,
        ).toBe("tool-call"),
      );

      act(() => {
        aui()
          .thread.message({ id: "a1" })
          .part({ toolCallId: "tc1" })
          .addToolResult(new ToolResponse({ result: "ok", artifact }));
      });

      await waitFor(() => expect(fetchMock.requests).toHaveLength(1));
      expect(fetchMock.requests[0]!.body["commands"][0]).toHaveProperty(
        "artifact",
        artifact,
      );

      act(() => fetchMock.servers[0]!.close());
      await waitFor(() =>
        expect(aui().thread.getState().isRunning).toBe(false),
      );
    },
  );

  it("forwards a tool response's modelContent to the outbound command", async () => {
    const fetchMock = installFetch();
    const { aui } = mountRuntime({
      converter: (_state, meta) => ({
        messages: [
          {
            id: "a1",
            role: "assistant",
            content: [
              {
                type: "tool-call",
                toolCallId: "tc1",
                toolName: "probe",
                args: {},
                argsText: "{}",
              },
            ],
            createdAt: new Date(0),
            status: { type: "requires-action", reason: "tool-calls" },
            metadata: {
              unstable_state: {},
              unstable_annotations: [],
              unstable_data: [],
              steps: [],
              custom: {},
            },
          },
        ],
        isRunning: meta.isSending,
      }),
    });

    await waitFor(() =>
      expect(
        aui()
          .thread.message({ id: "a1" })
          .part({ toolCallId: "tc1" })
          .getState().type,
      ).toBe("tool-call"),
    );

    const modelContent = [{ type: "text" as const, text: "done" }];
    act(() => {
      aui()
        .thread.message({ id: "a1" })
        .part({ toolCallId: "tc1" })
        .addToolResult(new ToolResponse({ result: "ok", modelContent }));
    });

    await waitFor(() => expect(fetchMock.requests).toHaveLength(1));
    expect(fetchMock.requests[0]!.body["commands"][0]).toHaveProperty(
      "modelContent",
      modelContent,
    );

    act(() => fetchMock.servers[0]!.close());
    await waitFor(() => expect(aui().thread.getState().isRunning).toBe(false));
  });

  it.each(["throws", "rejects"] as const)(
    "cancels the response body when onResponse %s",
    async (failureMode) => {
      const callbackError = new Error("response callback failed");
      const cancel = vi.fn().mockRejectedValue(new Error("cancel failed"));
      const onError = vi.fn();
      vi.stubGlobal(
        "fetch",
        vi.fn().mockResolvedValue(
          new Response(
            new ReadableStream({
              cancel,
            }),
          ),
        ),
      );

      const { aui, sendCommand } = mountRuntime({
        onResponse: () => {
          if (failureMode === "throws") throw callbackError;
          return Promise.reject(callbackError);
        },
        onError,
      });
      await waitFor(() =>
        expect(
          (aui().thread.getState().extras as { sendCommand?: unknown })
            ?.sendCommand,
        ).toBeTypeOf("function"),
      );

      act(() => sendCommand(createMessageCommand("hello")));

      await waitFor(() =>
        expect(onError).toHaveBeenCalledWith(callbackError, expect.anything()),
      );
      expect(cancel).toHaveBeenCalledOnce();
    },
