    const onFinish = vi.fn();
    const onResponse = vi
      .fn()
      .mockImplementationOnce(() => {
        throw new Error("boom");
      })
      .mockImplementation(() => {});
    const { aui, sendCommand } = mountRuntime({
      onError,
      onCancel,
      onFinish,
      onResponse,
    });
    await waitFor(() =>
      expect(
        (aui().thread.getState().extras as { sendCommand?: unknown })
          ?.sendCommand,
      ).toBeTypeOf("function"),
    );

    act(() => sendCommand(createMessageCommand("a")));
    await waitFor(() => expect(onError).toHaveBeenCalledTimes(1));
    act(() => sendCommand(createMessageCommand("b", "b-id")));
    expect(aui().thread.getState().isRunning).toBe(true);

    act(() => aui().thread.cancelRun());
    await waitFor(() => expect(aui().thread.getState().isRunning).toBe(false));
    expect(onFinish).toHaveBeenCalledTimes(1);
    expect(onCancel).toHaveBeenCalledTimes(1);
    expect(onCancel.mock.calls[0]![0].commands).toEqual([
      createMessageCommand("b", "b-id"),
    ]);

    act(() => sendCommand(createMessageCommand("c", "c-id")));
    await waitFor(() => expect(fetchMock.requests).toHaveLength(2));
    expect(fetchMock.requests[1]!.body["commands"]).toEqual([
      createMessageCommand("c", "c-id"),
    ]);
  });

  it("reports the commands queued before the failure once a cancelled run's onError settles", async () => {
    const fetchMock = installFetch();
    let failResponse!: (error: Error) => void;
    const responseFailed = new Promise<void>((_, reject) => {
      failResponse = reject;
    });
    const onResponse = vi
      .fn()
      .mockImplementationOnce(() => responseFailed)
      .mockImplementation(() => {});
    let settleOnError!: () => void;
    const onError = vi.fn(
      () =>
        new Promise<void>((resolve) => {
          settleOnError = resolve;
        }),
    );
    const onCancel = vi.fn();
    const { aui, sendCommand } = mountRuntime({
      onError,
      onCancel,
      onResponse,
    });
    await waitFor(() =>
      expect(
        (aui().thread.getState().extras as { sendCommand?: unknown })
          ?.sendCommand,
      ).toBeTypeOf("function"),
    );

    act(() => sendCommand(createMessageCommand("a")));
    await waitFor(() => expect(onResponse).toHaveBeenCalledTimes(1));
    act(() => sendCommand(createMessageCommand("b", "b-id")));
    const boom = new Error("boom");
    await act(async () => failResponse(boom));
    await waitFor(() => expect(onError).toHaveBeenCalledTimes(1));
    act(() => sendCommand(createMessageCommand("c", "c-id")));

    act(() => aui().thread.cancelRun());
    await waitFor(() => expect(aui().thread.getState().isRunning).toBe(false));
    expect(onCancel).toHaveBeenCalledTimes(1);
    expect(onCancel.mock.calls[0]![0]).not.toHaveProperty("error");
    expect(onCancel.mock.calls[0]![0].commands).toEqual([
      createMessageCommand("c", "c-id"),
    ]);

    act(() => sendCommand(createMessageCommand("d", "d-id")));
    await waitFor(() => expect(fetchMock.requests).toHaveLength(2));

    await act(async () => settleOnError());
    await waitFor(() => expect(onCancel).toHaveBeenCalledTimes(2));
    expect(onCancel.mock.calls[1]![0].error).toBe(boom);
    expect(onCancel.mock.calls[1]![0].commands).toEqual([
      createMessageCommand("b", "b-id"),
    ]);
    expect(fetchMock.requests[1]!.body["commands"]).toEqual([
      createMessageCommand("d", "d-id"),
    ]);
    expect(aui().thread.getState().isRunning).toBe(true);
    expect(onCancel).toHaveBeenCalledTimes(2);
  });

  it("ends a resumed run on cancelRun while its replay waits for a suspended render", async () => {
    const fetchMock = vi.fn(async (_url: string, init: RequestInit) => {
      const stream = new ReadableStream<Uint8Array>({
        start(controller) {
          init.signal!.addEventListener("abort", () =>
            controller.error(init.signal!.reason),
          );
        },
      });
      return new Response(stream, {
        headers: { [REPLAY_CONTENT_LENGTH_HEADER]: "10" },
      });
    });
    vi.stubGlobal("fetch", fetchMock);
    let released = false;
    let releaseSuspense!: () => void;
    const suspense = new Promise<void>((resolve) => {
      releaseSuspense = () => {
        released = true;
        resolve();
      };
    });
    let suspend!: () => void;
    const Suspender: FC = () => {
      const [suspended, setSuspended] = useState(false);
      suspend = () => setSuspended(true);
      if (!suspended) return null;
      if (!released) throw suspense;
      return <span data-testid="resumed" />;
    };
    const captured: { aui?: ReturnType<typeof useAui> } = {};
    const Capture: FC = () => {
      captured.aui = useAui();
      return null;
    };
    const onCancel = vi.fn();
    const App: FC = () => {
      const runtime = useAssistantTransportRuntime({
        initialState: {},
        api: "https://example.com/api",
        resumeApi: "https://example.com/resume",
        headers: {},
        converter,
        onCancel,
      });
      return (
        <AssistantRuntimeProvider runtime={runtime}>
          <Capture />
          <Suspender />
        </AssistantRuntimeProvider>
      );
    };
    const { findByTestId } = render(
      <Suspense fallback={null}>
        <App />
      </Suspense>,
    );
    const aui = () => captured.aui!;
    await waitFor(() =>
      expect(
        (aui().thread.getState().extras as { sendCommand?: unknown })
          ?.sendCommand,
      ).toBeTypeOf("function"),
    );

    act(() => suspend());
    act(() => {
      void aui().thread.resumeRun({ parentId: null });
    });
    await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(1));
    await act(async () => {});
    act(() => aui().thread.cancelRun());

    await waitFor(() => expect(onCancel).toHaveBeenCalledTimes(1));
    expect(aui().thread.getState().isRunning).toBe(false);

    await act(async () => releaseSuspense());
    await findByTestId("resumed");
    expect(aui().thread.getState().isRunning).toBe(false);
  });
});

import * as React from 'react';
import {
  NotificationProvider,
  useNotification as useRcNotification,
} from '@rc-component/notification';
import type {
  NotificationAPI,
  NotificationConfig as RcNotificationConfig,
  NotificationProps as RcNotificationProps,
} from '@rc-component/notification';
import { isNonNullable } from '@rc-component/util';
import { clsx } from 'clsx';

import {
  resolveStyleOrClass,
  useMergeSemantic,
  useSemanticRootStyle,
} from '../_util/hooks/useMergeSemantic';
import { isFunction, isPlainObject } from '../_util/is';
import { devUseWarning } from '../_util/warning';
import { ConfigContext } from '../config-provider';
import { useComponentConfig } from '../config-provider/context';
import type { MessageConfig } from '../config-provider/context';
import useCSSVarCls from '../config-provider/hooks/useCSSVarCls';
import useStackConfig from '../notification/hooks/useStackConfig';
import { getPlacementOffsetStyle } from '../notification/util';
import type {
  ArgsProps,
  ConfigOptions,
  MessageInstance,
  MessageType,
  NoticeType,
  TypeOpen,
} from './interface';
import { getMessageIcon } from './PurePanel';
import useStyle from './style';
import { getMotion, wrapPromiseFn } from './util';

const DEFAULT_OFFSET = 8;
const DEFAULT_DURATION = 3;
const DEFAULT_STACK_CONFIG = false;

// ==============================================================================
// ==                                  Holder                                  ==
// ==============================================================================
type HolderProps = ConfigOptions & {
  onAllRemoved?: VoidFunction;
};

interface HolderRef extends NotificationAPI {
  prefixCls: string;
  message?: MessageConfig;
}

const Wrapper: React.FC<React.PropsWithChildren<{ prefixCls: string }>> = ({
  children,
  prefixCls,
}) => {
  const rootCls = useCSSVarCls(prefixCls);
  const [hashId, cssVarCls] = useStyle(prefixCls, rootCls);
  return (
    <NotificationProvider classNames={{ list: clsx(hashId, cssVarCls, rootCls) }}>
      {children}
    </NotificationProvider>
  );
};

const renderNotifications: RcNotificationConfig['renderNotifications'] = (
  node,
  { prefixCls, key },
) => (
  <Wrapper prefixCls={prefixCls} key={key}>
    {node}
  </Wrapper>
);

const Holder = React.forwardRef<HolderRef, HolderProps>((props, ref) => {
  const {
    // Placement
    top,

    // Config
    prefixCls: staticPrefixCls,
    getContainer: staticGetContainer,
    maxCount,
    duration = DEFAULT_DURATION,

    // Style
    rtl,
    classNames,
    styles,

    // Motion
    transitionName,

    // UI
    pauseOnHover = true,
    stack,

    // Life Cycle
    onAllRemoved,
  } = props;
  const { getPrefixCls, direction, getPopupContainer } = useComponentConfig('message');
  const { message } = React.useContext(ConfigContext);

  const prefixCls = staticPrefixCls || getPrefixCls('message');

  // Use useMergeSemantic to merge classNames and styles
  const contextStyleRoot = useSemanticRootStyle(message?.style);

  const [mergedClassNames, mergedStyles] = useMergeSemantic(
    [message?.classNames, classNames],
    [message?.styles, contextStyleRoot, styles],
    {
      props: props as unknown as ArgsProps,
    },
  );
  // =============================== Style ===============================
  const getStyle = (): React.CSSProperties => getPlacementOffsetStyle(top ?? DEFAULT_OFFSET);

  const getClassName = () => clsx({ [`${prefixCls}-rtl`]: rtl ?? direction === 'rtl' });

  // ============================== Motion ===============================
  const getNotificationMotion = () => getMotion(prefixCls, transitionName);

  // =============================== Stack ===============================
  const stackConfig = useStackConfig(stack, DEFAULT_STACK_CONFIG);

  // ============================== Origin ===============================
  const [api, holder] = useRcNotification({
    prefixCls,
    style: getStyle,
    className: getClassName,
    motion: getNotificationMotion,

    // closable=false requires-no closeIcon
    closable: false,
    duration,
    getContainer: () => staticGetContainer?.() || getPopupContainer?.() || document.body,
    maxCount,
    onAllRemoved,
    classNames: mergedClassNames,
    styles: mergedStyles,
    renderNotifications,
    pauseOnHover,
    stack: stackConfig,
  });

  // ================================ Ref ================================
  React.useImperativeHandle(ref, () => ({
    ...api,
    prefixCls,
    message,
  }));

  return holder;
});

// ==============================================================================
// ==                                   Hook                                   ==
// ==============================================================================
let keyIndex = 0;

export function useInternalMessage(
  messageConfig?: HolderProps,
): readonly [MessageInstance, React.ReactElement] {
  const holderRef = React.useRef<HolderRef>(null);

  const warning = devUseWarning('Message');

  // ================================ API ================================
  const wrapAPI = React.useMemo<MessageInstance>(() => {
    // Wrap with notification content

    // >>> close
    const close = (key: React.Key) => {
      holderRef.current?.close(key);
    };

    // >>> Open
    const open = (config: ArgsProps): MessageType => {
      if (!holderRef.current) {
        warning(
          false,
          'usage',
          'You are calling notice in render which will break in React 18 concurrent mode. Please trigger in effect instead.',
        );
        const fakeResult: any = () => {};
        fakeResult.then = () => {};
        return fakeResult;
      }

      const { open: originOpen, prefixCls, message } = holderRef.current;

      const contextClassName = message?.className || {};
      const noticePrefixCls = `${prefixCls}-notice`;

      const {
        content,
        icon,
        type,
        key,
        className,
        style,
        onClose,
        classNames: configClassNames = {},
        styles = {},
        ...restConfig
      } = config;

      let mergedKey: React.Key = key!;
      if (!isNonNullable(mergedKey)) {
        keyIndex += 1;
        mergedKey = `antd-message-${keyIndex}`;
      }

      const contextConfig: HolderProps = { ...messageConfig, ...config };

      const semanticClassNames = resolveStyleOrClass(configClassNames, { props: contextConfig });
      const semanticStyles = resolveStyleOrClass(styles, { props: contextConfig });
      const iconNode = getMessageIcon(type, icon);
      const typeIconCls = type ? `${noticePrefixCls}-icon-${type}` : undefined;

      return wrapPromiseFn((resolve) => {
        originOpen({
          ...restConfig,
          key: mergedKey,
          icon: iconNode,
          title: content,
          classNames: {
            ...semanticClassNames,
            wrapper: clsx(type && `${prefixCls}-${type}`, semanticClassNames?.wrapper),
            icon: clsx(typeIconCls, semanticClassNames?.icon),
          } satisfies RcNotificationProps['classNames'],
          styles: semanticStyles satisfies RcNotificationProps['styles'],
          placement: 'top',
          className: clsx({ [`${noticePrefixCls}-${type}`]: type }, className, contextClassName),
          style,
          onClose: () => {
            onClose?.();
            resolve();
          },
        });

        // Return close function
        return () => {
          close(mergedKey);
        };
      });
    };

    // >>> destroy
    const destroy = (key?: React.Key) => {
      if (key !== undefined) {
        close(key);
      } else {
        holderRef.current?.destroy();
      }
    };

    const clone = {
      open,
      destroy,
    } as MessageInstance;

    const keys: NoticeType[] = ['info', 'success', 'warning', 'error', 'loading'];
    keys.forEach((type) => {
      const typeOpen: TypeOpen = (jointContent, duration, onClose) => {
        let config: ArgsProps;
        if (isPlainObject(jointContent) && 'content' in jointContent) {
          config = jointContent;
        } else {
          config = { content: jointContent };
        }

        // Params
        let mergedDuration: number | undefined;
        let mergedOnClose: VoidFunction | undefined;
        if (isFunction(duration)) {
          mergedOnClose = duration;
        } else {
          mergedDuration = duration;
          mergedOnClose = onClose;
        }

        const mergedConfig = {
          onClose: mergedOnClose,
          duration: mergedDuration,
          ...config,
          type,
        };

        return open(mergedConfig);
      };

      clone[type] = typeOpen;
    });

    return clone;
  }, []);

  // ============================== Return ===============================
  return [wrapAPI, <Holder key="message-holder" {...messageConfig} ref={holderRef} />] as const;
}

export default function useMessage(messageConfig?: ConfigOptions) {
  return useInternalMessage(messageConfig);
}

// @vitest-environment jsdom

import {
  act,
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import {
  afterAll,
  afterEach,
  beforeAll,
  describe,
  expect,
  it,
  vi,
} from "vitest";
import { useEffect, useState, type FC, type PropsWithChildren } from "react";
import { useAuiState } from "@assistant-ui/store";
import { AssistantRuntimeProvider } from "../../context";
import {
  useThreadViewport,
  useThreadViewportStore,
} from "../../context/react/ThreadViewportContext";
import * as MessagePrimitive from "../message";
import { ThreadPrimitiveMessages } from "./ThreadMessages";
import { ThreadPrimitiveRoot } from "./ThreadRoot";
import { ThreadPrimitiveScrollToBottom } from "./ThreadScrollToBottom";
import { ThreadPrimitiveViewport } from "./ThreadViewport";
import {
  ExportedMessageRepository,
  useExternalStoreRuntime,
  useLocalRuntime,
  type ChatModelAdapter,
  type ThreadHistoryAdapter,
  type ThreadMessageLike,
} from "../../index";
import { ThreadPrimitiveLoadEarlier } from "./ThreadLoadEarlier";

const adapter: ChatModelAdapter = {
  async *run() {},
};

const messages: ThreadMessageLike[] = Array.from({ length: 8 }, (_, index) => ({
  role: index % 2 === 0 ? "user" : "assistant",
  content: [{ type: "text", text: `Message ${index + 1}` }],
}));

const getViewport = () => screen.getByTestId("viewport");

const getMaxScrollTop = (element: Element) =>
  Math.max(0, element.scrollHeight - element.clientHeight);

let forceShortViewportMeasurement = false;
let viewportMeasurementOffset = 0;
const messageHeights = new Map<string, number>();
const resizeObservers = new Set<TestResizeObserver>();

const messageRows = () => [
  ...document.querySelectorAll<HTMLElement>('[data-testid="thread-message"]'),
];

const rowHeight = (row: Element) =>
  messageHeights.get(row.getAttribute("data-message-id") ?? "") ?? 80;

const rowsHeight = (rows: readonly Element[]) =>
  rows.reduce((height, row) => height + rowHeight(row), 0);

class TestResizeObserver {
  readonly targets = new Set<Element>();
  readonly callback: ResizeObserverCallback;

  constructor(callback: ResizeObserverCallback) {
    this.callback = callback;
    resizeObservers.add(this);
  }

  observe(target: Element) {
    this.targets.add(target);
  }
  unobserve(target: Element) {
    this.targets.delete(target);
  }
  disconnect() {
    resizeObservers.delete(this);
  }
}

const notifyResizeObservers = () => {
  for (const observer of resizeObservers) {
    observer.callback([], {} as ResizeObserver);
  }
};

/** Resizes only `target`, as a child growing without a DOM mutation does. */
const notifyResizeOf = (target: Element) => {
  for (const observer of resizeObservers) {
    if (observer.targets.has(target)) {
      observer.callback([], {} as ResizeObserver);
    }
  }
};

const descriptors = {
  scrollTop: Object.getOwnPropertyDescriptor(
    HTMLElement.prototype,
    "scrollTop",
  ),
  scrollHeight: Object.getOwnPropertyDescriptor(
    HTMLElement.prototype,
    "scrollHeight",
  ),
  clientHeight: Object.getOwnPropertyDescriptor(
    HTMLElement.prototype,
    "clientHeight",
  ),
  scrollTo: Object.getOwnPropertyDescriptor(HTMLElement.prototype, "scrollTo"),
};

const scrollTopByElement = new WeakMap<Element, number>();

beforeAll(() => {
  vi.stubGlobal("ResizeObserver", TestResizeObserver);
  vi.stubGlobal("requestAnimationFrame", (callback: FrameRequestCallback) =>
    window.setTimeout(() => callback(performance.now()), 0),
  );
  vi.stubGlobal("cancelAnimationFrame", (id: number) =>
    window.clearTimeout(id),
  );

  Object.defineProperty(HTMLElement.prototype, "scrollTop", {
    configurable: true,
    get() {
      return scrollTopByElement.get(this) ?? 0;
    },
    set(value: number) {
      scrollTopByElement.set(this, value);
    },
  });

  Object.defineProperty(HTMLElement.prototype, "clientHeight", {
    configurable: true,
    get() {
      return this.getAttribute("data-testid") === "viewport" ? 100 : 0;
    },
  });

  Object.defineProperty(HTMLElement.prototype, "scrollHeight", {
    configurable: true,
    get() {
      if (this.getAttribute("data-testid") !== "viewport") return 0;
      if (forceShortViewportMeasurement) return this.clientHeight;
      return rowsHeight(messageRows()) + viewportMeasurementOffset;
    },
  });

  Object.defineProperty(HTMLElement.prototype, "getBoundingClientRect", {
    configurable: true,
    value(this: HTMLElement) {
      const rows = messageRows();
      const index = rows.indexOf(this);
      const viewport = this.closest<HTMLElement>('[data-testid="viewport"]');
      const top =
        index === -1
          ? 0
          : rowsHeight(rows.slice(0, index)) - (viewport?.scrollTop ?? 0);
      const height = index === -1 ? 0 : rowHeight(this);
      return {
        x: 0,
        y: top,
        top,
        bottom: top + height,
        left: 0,
        right: 0,
        width: 0,
        height,
        toJSON: () => ({}),
      } satisfies DOMRect;
    },
  });

  Object.defineProperty(HTMLElement.prototype, "scrollTo", {
    configurable: true,
    value({ top = 0 }: ScrollToOptions) {
      this.scrollTop = Math.min(Number(top), getMaxScrollTop(this));
      this.dispatchEvent(new Event("scroll"));
    },
  });
});

afterEach(() => {
  forceShortViewportMeasurement = false;
  viewportMeasurementOffset = 0;
  messageHeights.clear();
  resizeObservers.clear();
  cleanup();
});

afterAll(() => {
  vi.unstubAllGlobals();

  for (const [key, descriptor] of Object.entries(descriptors)) {
    if (descriptor) {
      Object.defineProperty(HTMLElement.prototype, key, descriptor);
    }
  }
});

